CREATE TABLE IF NOT EXISTS admin_users (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,admin_id VARCHAR(50) UNIQUE NOT NULL,username VARCHAR(512),username_lookup CHAR(64),password VARCHAR(255) NOT NULL,full_name VARCHAR(512),role VARCHAR(20) DEFAULT 'admin',profile_image VARCHAR(255),source_user_id VARCHAR(50),login_enabled SMALLINT NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id VARCHAR(50) UNIQUE NOT NULL,username VARCHAR(512),username_lookup CHAR(64),password VARCHAR(255),full_name VARCHAR(512),address VARCHAR(512),email VARCHAR(512),contact_number VARCHAR(512),contact_lookup CHAR(64),qr_code_path VARCHAR(255),status VARCHAR(20) DEFAULT 'approved',loyalty_points INTEGER DEFAULT 0,points_year INTEGER,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS rider_users (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,rider_id VARCHAR(50) UNIQUE NOT NULL,username VARCHAR(512),username_lookup CHAR(64),password VARCHAR(255) NOT NULL,full_name VARCHAR(512),age INTEGER,address VARCHAR(512),contact_number VARCHAR(512),contact_lookup CHAR(64),status VARCHAR(20) DEFAULT 'active',source_user_id VARCHAR(50),login_enabled SMALLINT NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS inventory_items (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,item_code VARCHAR(50) UNIQUE NOT NULL,item_name VARCHAR(150) NOT NULL,category VARCHAR(80) NOT NULL DEFAULT 'Container',quantity INTEGER NOT NULL DEFAULT 0,minimum_stock INTEGER NOT NULL DEFAULT 10,unit_price NUMERIC(10,2) NOT NULL DEFAULT 0,updated_by VARCHAR(80),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS transactions (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,transaction_id VARCHAR(50) UNIQUE NOT NULL,user_id VARCHAR(50) NOT NULL,amount NUMERIC(10,2) DEFAULT 0,status VARCHAR(20) DEFAULT 'pending',description TEXT,water_type VARCHAR(20) DEFAULT 'regular',quantity INTEGER DEFAULT 1,price_per_unit NUMERIC(10,2),discount NUMERIC(10,2) DEFAULT 0,notes TEXT,delivery_status VARCHAR(30) DEFAULT 'pending',assigned_rider VARCHAR(255),approved_by VARCHAR(50),payment_method VARCHAR(20) DEFAULT 'cash',payment_reference VARCHAR(255),payment_status VARCHAR(20) DEFAULT 'pending',payment_date TIMESTAMP,payment_proof VARCHAR(255),rider_id VARCHAR(50),loyalty_points_earned INTEGER DEFAULT 0,amount_tendered NUMERIC(10,2),"change" NUMERIC(10,2),container_size VARCHAR(30),container_status VARCHAR(20),fulfillment_method VARCHAR(20),inventory_item_id INTEGER,inventory_reserved SMALLINT NOT NULL DEFAULT 0,new_container_inventory_item_id INTEGER,new_container_inventory_reserved SMALLINT NOT NULL DEFAULT 0,cancellation_reason VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS rider_locations (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,transaction_id VARCHAR(50) NOT NULL,rider_id VARCHAR(50),rider_latitude NUMERIC(10,8) NOT NULL DEFAULT 12.8797,rider_longitude NUMERIC(11,8) NOT NULL DEFAULT 121.7740,accuracy DOUBLE PRECISION,speed DOUBLE PRECISION,heading DOUBLE PRECISION,last_update TIMESTAMP DEFAULT CURRENT_TIMESTAMP,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS rider_notifications (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,rider_id VARCHAR(50) NOT NULL,transaction_id VARCHAR(50) NOT NULL,title VARCHAR(255) NOT NULL,message TEXT NOT NULL,is_read SMALLINT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS rider_messages (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,transaction_id VARCHAR(50) NOT NULL,sender VARCHAR(50) NOT NULL,recipient VARCHAR(50) NOT NULL,message TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS feedback_ratings (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,transaction_id VARCHAR(255) NOT NULL,user_id VARCHAR(255) NOT NULL,rating INTEGER NOT NULL,feedback_message TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(transaction_id,user_id));
CREATE TABLE IF NOT EXISTS payments (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,payment_id VARCHAR(255) UNIQUE NOT NULL,transaction_id VARCHAR(255) NOT NULL,user_id VARCHAR(255) NOT NULL,amount NUMERIC(10,2) NOT NULL,payment_method VARCHAR(20) NOT NULL,payment_reference VARCHAR(255),payment_status VARCHAR(20) DEFAULT 'pending',payment_proof VARCHAR(255),gcash_number VARCHAR(20),maya_number VARCHAR(20),notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS admin_settings (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,admin_id VARCHAR(50) UNIQUE NOT NULL,settings TEXT NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS admin_profiles (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,admin_id VARCHAR(50) UNIQUE NOT NULL,first_name VARCHAR(512),last_name VARCHAR(512),email VARCHAR(512),phone VARCHAR(512),avatar_path VARCHAR(255),updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS payment_qr_settings (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,payment_method VARCHAR(20) UNIQUE NOT NULL,qr_image_path VARCHAR(255) NOT NULL,account_number VARCHAR(50) NOT NULL DEFAULT '',account_name VARCHAR(100) NOT NULL DEFAULT '',updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS inventory_movements (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,item_id INTEGER NOT NULL,movement_type VARCHAR(20) NOT NULL,quantity_change INTEGER NOT NULL,previous_quantity INTEGER NOT NULL,new_quantity INTEGER NOT NULL,reason VARCHAR(255),staff_id VARCHAR(80) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user_notifications (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id VARCHAR(255) NOT NULL,transaction_id VARCHAR(255),title VARCHAR(150) NOT NULL,message VARCHAR(500) NOT NULL,notification_type VARCHAR(30) NOT NULL DEFAULT 'info',is_read SMALLINT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reward_claims (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,transaction_id VARCHAR(50) UNIQUE NOT NULL,user_id VARCHAR(50) NOT NULL,reward_code VARCHAR(80) NOT NULL,reward_title VARCHAR(255) NOT NULL,points_used INTEGER NOT NULL,claim_status VARCHAR(20) NOT NULL DEFAULT 'pending',claimed_by VARCHAR(80),claimed_at TIMESTAMP,customer_seen_at TIMESTAMP,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS system_settings (setting_key VARCHAR(80) PRIMARY KEY,setting_value VARCHAR(500) NOT NULL,updated_by VARCHAR(80),updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS system_activity_logs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,actor_id VARCHAR(80),actor_name VARCHAR(255),actor_role VARCHAR(30),action VARCHAR(120) NOT NULL,entity_type VARCHAR(80),entity_id VARCHAR(100),description TEXT,page VARCHAR(255),request_method VARCHAR(10),ip_address VARCHAR(45),user_agent VARCHAR(500),metadata TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE system_activity_logs ADD COLUMN IF NOT EXISTS actor_name VARCHAR(255);
ALTER TABLE system_activity_logs ADD COLUMN IF NOT EXISTS page VARCHAR(255);
ALTER TABLE system_activity_logs ADD COLUMN IF NOT EXISTS request_method VARCHAR(10);
ALTER TABLE system_activity_logs ADD COLUMN IF NOT EXISTS user_agent VARCHAR(500);
ALTER TABLE system_activity_logs ADD COLUMN IF NOT EXISTS metadata TEXT;
CREATE TABLE IF NOT EXISTS activity_logs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,admin_id VARCHAR(80),action VARCHAR(255) NOT NULL,description TEXT,"timestamp" TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS hydromis_sessions (session_id VARCHAR(128) PRIMARY KEY,payload TEXT NOT NULL,expires_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_hydromis_sessions_expiry ON hydromis_sessions(expires_at);
CREATE INDEX IF NOT EXISTS idx_transactions_user ON transactions(user_id,created_at);
CREATE INDEX IF NOT EXISTS idx_rider_location_transaction ON rider_locations(transaction_id,last_update);
CREATE INDEX IF NOT EXISTS idx_inventory_created ON inventory_movements(created_at);
CREATE INDEX IF NOT EXISTS idx_user_notification ON user_notifications(user_id,is_read,created_at);
